[notice] A new release of pip is available: 25.2 -> 26.2.1
[notice] To update, run: pip install --upgrade pip
{
 "language": "python",
 "dist": "xenial",
 "matrix": {
  "include": [
   {
    "python": "3.7"
   },
   {
    "python": "3.8"
   },
   {
    "python": "3.9"
   }
  ]
 },
 "addons": {
  "apt": {
   "packages": [
    "libgmp-dev",
    "libmpfr-dev",
    "libmpc-dev"
   ]
  }
 },
 "install": [
  "pip install --upgrade pip setuptools wheel",
  "pip install gmpy2",
  "pip install \".[cli]\"",
  "pip install pytest"
 ],
 "script": [
  "python -m pytest phe/tests"
 ]
}
